std::mutex resource_mtx;
int shared_resource = 0;

void access_critical_section() {
    // RAII guarantees release upon scope exit
    std::lock_guard<std::mutex> lock(resource_mtx);
    shared_resource += 1;
}


std::mutex queue_mtx;
std::condition_variable cv;
std::queue<Data> buffer;

void consumer_wait() {
    std::unique_lock<std::mutex> lock(queue_mtx);
    // Wait until buffer is not empty
    cv.wait(lock, []{ return !buffer.empty(); });
    Data item = buffer.front();
}
void producer_signal() {
    // Populate buffer
    cv.notify_one();
}


// Lock-free resource counter
std::atomic<long> active_transactions(0);
std::atomic<bool> system_initialized(false);

void start_transaction() {
    active_transactions++;
}

bool try_initialize() {
    // Compare and Swap loop
    return system_initialized.compare_exchange_strong(
        false, true
    );
}


// Shared Mutex (Read-Write Lock)
std::shared_mutex rw_mtx;
int cached_data = 100;

void reader_thread() {
    // Allows multiple concurrent readers
    std::shared_lock<std::shared_mutex> lock(rw_mtx);
    int temp = cached_data;
}

void writer_thread() {
    // Exclusive access for writing
    std::unique_lock<std::shared_mutex> lock(rw_mtx);
    cached_data = 200;
}
